#!/usr/bin/env python3<br>import subprocess, os, json, time, sys, urllib.request<br><br>ROOT = <mark>/mnt/agents/output</mark><br>PAT = open(f<mark>{ROOT}/.env</mark>).read().split(<mark>GITHUB_PAT=</mark>)[1].split()[0]<br><br>def run(cmd, cwd=ROOT, timeout=60, shell=False):<br>    if isinstance(cmd, str): shell = True<br>    try:<br>        r = subprocess.run(cmd, shell=shell, capture_output=True, text=True, timeout=timeout, cwd=cwd)<br>        return {<mark>ok</mark>: r.returncode == 0, <mark>rc</mark>: r.returncode, <mark>out</mark>: r.stdout, <mark>err</mark>: r.stderr}<br>    except Exception as e:<br>        return {<mark>ok</mark>: False, <mark>rc</mark>: -1, <mark>out</mark>: <mark></mark>, <mark>err</mark>: str(e)}<br><br>results = {}<br><br># Check bun<br>results[<mark>bun</mark>] = run([<mark>/root/.bun/bin/bun</mark>, <mark>--version</mark>])<br>if not results[<mark>bun</mark>][<mark>ok</mark>]:<br>    results[<mark>bun_install</mark>] = run(<mark>curl -fsSL https://bun.sh/install | bash</mark>, shell=True, timeout=120)<br><br># Fix perms<br>run(<mark>chown -R root:root /mnt/agents/output && chmod -R u+rw /mnt/agents/output</mark>, shell=True)<br><br># Remove lock files<br>for repo in [<mark>app</mark>, <mark>triangle-access</mark>]:<br>    for lock in [<mark>bun.lock</mark>, <mark>bun.lockb</mark>, <mark>package-lock.json</mark>]:<br>        p = f<mark>{ROOT}/{repo}/{lock}</mark><br>        if os.path.exists(p): os.remove(p)<br><br># Fix git safe dirs<br>for d in [<mark>app</mark>, <mark>triangle-access</mark>, <mark>.git_repos/effusion-labs.git</mark>, <mark>.triangle-git-metadata</mark>]:<br>    run([<mark>git</mark>, <mark>config</mark>, <mark>--global</mark>, <mark>--add</mark>, <mark>safe.directory</mark>, f<mark>{ROOT}/{d}</mark>])<br><br># Effusion-labs<br>os.chdir(f<mark>{ROOT}/app</mark>)<br>run([<mark>rm</mark>, <mark>-f</mark>, <mark>.git</mark>])<br>run([<mark>git</mark>, <mark>init</mark>, f<mark>--separate-git-dir={ROOT}/.git_repos/effusion-labs.git</mark>])<br>run([<mark>git</mark>, <mark>config</mark>, <mark>user.email</mark>, <mark>agent@many-never-one.local</mark>])<br>run([<mark>git</mark>, <mark>config</mark>, <mark>user.name</mark>, <mark>ManyNeverOne Agent</mark>])<br>run(f<mark>git remote add origin https://{PAT}@github.com/toxicwind/effusion-labs.git</mark>, shell=True)<br>run([<mark>git</mark>, <mark>fetch</mark>, <mark>origin</mark>, <mark>main</mark>, <mark>--depth=1</mark>])<br>run([<mark>git</mark>, <mark>reset</mark>, <mark>--soft</mark>, <mark>origin/main</mark>])<br><br># Write CI<br>with open(<mark>.github/workflows/ci.yml</mark>, <mark>w</mark>) as f:<br>    f.write(<mark>name: CI Build</mark> + <mark>on: push: branches: [main]</mark> + <mark>jobs: build: runs-on: ubuntu-latest steps: - uses: actions/checkout@v4 - uses: oven-sh/setup-bun@v2 - run: bun install --no-save - run: bun run build</mark>)<br><br>run([<mark>git</mark>, <mark>add</mark>, <mark>-A</mark>])<br>ef = run([<mark>git</mark>, <mark>commit</mark>, <mark>-m</mark>, f<mark>fix: no locks, setup-bun {time.time()}</mark>])<br>ef_push = run(f<mark>git push https://{PAT}@github.com/toxicwind/effusion-labs.git main --force</mark>, shell=True, timeout=60)<br><br># Triangle-access<br>os.chdir(f<mark>{ROOT}/triangle-access</mark>)<br>run([<mark>rm</mark>, <mark>-f</mark>, <mark>.git</mark>])<br>run([<mark>git</mark>, <mark>init</mark>, f<mark>--separate-git-dir={ROOT}/.triangle-git-metadata</mark>])<br>run([<mark>git</mark>, <mark>config</mark>, <mark>user.email</mark>, <mark>agent@many-never-one.local</mark>])<br>run([<mark>git</mark>, <mark>config</mark>, <mark>user.name</mark>, <mark>ManyNeverOne Agent</mark>])<br>run(f<mark>git remote add origin https://{PAT}@github.com/toxicwind/triangle-access.git</mark>, shell=True)<br>run([<mark>git</mark>, <mark>fetch</mark>, <mark>origin</mark>, <mark>main</mark>, <mark>--depth=1</mark>])<br>run([<mark>git</mark>, <mark>reset</mark>, <mark>--soft</mark>, <mark>origin/main</mark>])<br>run([<mark>git</mark>, <mark>add</mark>, <mark>-A</mark>])<br>ta = run([<mark>git</mark>, <mark>commit</mark>, <mark>-m</mark>, f<mark>auto: sync {time.time()}</mark>])<br>ta_push = run(f<mark>git push https://{PAT}@github.com/toxicwind/triangle-access.git main --force</mark>, shell=True, timeout=60)<br><br># Check CI<br>try:<br>    req = urllib.request.Request(<mark>https://api.github.com/repos/toxicwind/effusion-labs/actions/runs?per_page=3</mark>, headers={<mark>Authorization</mark>: f<mark>token {PAT}</mark>})<br>    resp = urllib.request.urlopen(req, timeout=10).read().decode()<br>    data = json.loads(resp)<br>    ci = <mark> </mark>.join([f<mark>{r['name']} | {r['status']} | {r.get('conclusion','N/A')} | {r['head_sha'][:8]}</mark> for r in data.get(<mark>workflow_runs</mark>, [])[:3]])<br>except Exception as e:<br>    ci = str(e)<br><br>print(f<mark>EF: commit={ef['ok']} push={ef_push['ok']}</mark>)<br>print(f<mark>TA: commit={ta['ok']} push={ta_push['ok']}</mark>)<br>print(f<mark>CI: {ci}</mark>)<br>